############
### Function from AON_HMLL_auxiliary.jl
### Quality of clustering
############

# Adjusted Rand Index
function ari(x,y)
    evaluations = randindex(x, y)
    ari = evaluations[1]
    return ari
end


############
### Function from Chodrow et al. to read data
### (slightly modified to accept more general forms of dataname)
############

function read_hypergraph_edges(dataname::String, maxsize::Int64=1000, minsize::Int64=2)
    E = Dict{Integer, Dict}()
    open(string(dataname,"_he.txt")) do f
        for line in eachline(f)
            edge = [parse(Int64, v) for v in split(line, ',')]
            sort!(edge)
            if minsize <= length(edge) <= maxsize
                sz = length(edge)
                if !haskey(E, sz)
                    E[sz] = Dict{}()
                end
                E[sz][edge] = 1
            end
        end
    end
    return E
end


######
function parse_commandline()
    s = ArgParse.ArgParseSettings()

    ArgParse.@add_arg_table! s begin
        "-d"
            arg_type = String
            default = "./"
            help = "data directory"
        "-m"
            arg_type = String
            required = true
            help = "generating model"
        "-s"
            arg_type = String
            required = true
            help = "scenario (parameter choice)"
        "-n"
            arg_type = Int64
            default = 25
            help  = "num of hypergraphs in the scenario"
        "-t"
            arg_type = Int64
            required = true
            help  = "number of threads"
        "-i"
            arg_type = String
            default = ""
            help  = "which instances to use: e.g. 1,2,5"
        "-v"
            arg_type = String
            default = "default"
            help = "version of mt-kahypar used (for output file naming)"
        
    end
    s.usage = "julia AON_HMLL_script.jl -d <data_root_dir> -m <model> -s <scen> -i \"1,2,3\" -t <num_threads>"

    return ArgParse.parse_args(s)
end
######

# exemple of a command
# julia AON_HMLL_script.jl -v "test" -d "survey_benchmark/" -m "HyperSBM/" -s "scenA1/" -i "1,2,3" -t 3



#######################
#######################
function main()
    parsed_args = parse_commandline()
    
    ###### PARSE ARGUMENTS ######
    data_root_dir = parsed_args["d"]
    cd(data_root_dir)
    model = parsed_args["m"]
    scenario = parsed_args["s"]
    nreps =  parsed_args["n"]
    nthreads = parsed_args["t"]
    version = parsed_args["v"]
    instances_str = parsed_args["i"]
    if instances_str != ""
        instances = parse.(Int64, split(instances_str, ","))
        nreps = length(instances)
    else 
        instances = 1:nreps
    end

    
    ###### INITIALIZATIONS OF VARIABLES ######
    # Ari = zeros(Float64, nreps)
    runtimes = zeros(Float64, nreps)
    Q = zeros(Float64, nreps)
    Q_true = zeros(Float64, nreps)
    K_true = zeros(Int64, nreps)
    K_hat = zeros(Int64, nreps)
    relative_K_error = zeros(Float64, nreps)
    # conductance_hat = zeros(Float64, nreps)
    relative_mod_error = zeros(Float64, nreps)

    ###### GET RUNNING TIMES & CONDUCTANCES ######
    filename = string(model,scenario,"$(version).results.t_c")
    lines = readlines(filename)
    times = String[]
    # conductances = String[]
    for line in lines
        metric = split(line, "=")[1]
        if metric == "Time (sec.) "
            # times are in line "Time (sec.) = [t1, t2, ..., tn]"
            times_str = split(split(line, "=")[2], "[")[2]
            times_str = split(times_str, "]")[1]
            times = split(times_str, ",")
        # elseif metric == "Conductance "
            # conductance_hat are in line "Conductance = [c1, c2, ..., cn]"
        #    conductance_str = split(split(line, "=")[2], "[")[2]
        #    conductance_str = split(conductance_str, "]")[1]
        #    conductances = split(conductance_str, ",")
        end
    end
    runtimes = parse.(Float64, times)
    # conductance_hat = parse.(Float64, conductances)

    ###### LOOP OVER DATASETS ######
    for i in 1:nreps
        instance = instances[i]
        # print("\n Instance: $instance \n")
        # read true label vector
        filename = string(model,scenario,"rep",instance,"_assign.txt")
        Z_true = vec(readdlm(filename, Int))
        Z_hat = vec(readdlm(string(model,scenario,version,"/rep",instance,"_he.hgr.part"), Int))
        Z_hat .+= 1  # add 1 to each element of Z_hat
        K_true[i] = length(unique(Z_true)) # true number of clusters
        K_hat[i]= length(unique(Z_hat)) # estimated number of clusters
        relative_K_error[i] = (K_true[i] - K_hat[i])/(K_true[i])

        # read data
        filename = string(model,scenario,"rep",instance)
        E = read_hypergraph_edges(filename) # possible to add min and max hyperedge size
        n = maximum([maximum(e) for k in keys(E) for e in keys(E[k])])
        D = zeros(Int64, n)
        for (sz, edges) in E
            for (e, _) in edges
                D[e] .+= 1
            end
        end
        maxedges = maximum(keys(E))
        for k in 1:maxedges
            if !haskey(E, k)
                E[k] = Dict{}()
            end
        end
        # construct hypergraph
        N = 1:n
        H = hypergraph(N, E, D)
        
        ######## Extract omega parameters to compute modularity ######
        # compute initialisation corresponding to startclusters = "cliquelouvain"
        Z0 = HyperModularity.CliqueExpansionModularity(H,1.0) # default value gamma=1.0
        He2n, weights = HyperModularity.hypergraph2incidence(H)
        e2n = incidence2elist(He2n)
        d = 1.0*H.D # degree vector - coercion to float for compatibility with AON_louvain
        β, γ,omega = learn_omega_aon(e2n,weights,Z0,maxedges,d,n)
        
        Q[i] = modularity_aon(H,Z_hat,omega)
        Q_true[i] = modularity_aon(H,Z_true,omega)
        relative_mod_error[i] = (Q_true[i] - Q[i])/(Q_true[i])
       
        ######### Compute ARI #######
        #Ari[i] = ari(Z_hat,Z_true)
        
        # save partial results
        filename= string(model,scenario,"$(version).partial_results")
        
        open(filename, "w") do f
            write(f, "CPU time = $runtimes"*"\n"*"Modularity = $Q"*"\n"*"GT_Modularity = $Q_true"*"\n"*"Relative Modularity error = $relative_mod_error"*"\n"*"K = $K_hat"*"\n"*"GT_K = $K_true"*"\n"*"Relative k error = $relative_K_error"*"\n"*"Instances = $(instances)"*"\n")
            # write(f, "CPU time = $runtimes"*"\n"*"Modularity = $Q"*"\n"*"GT_Mod = $Q_true"*"\n"*"Relative Mod. error = $relative_mod_error"*"\n"*"K_hat = $K_hat"*"\n"*"K_true = $K_true"*"\n"*"Relative k error = $relative_K_error"*"\n"*"Conductance_hat = $conductance_hat"*"\n"*"Instances = $(instances)")
            # write(f, "ARI = $Ari"*"\n"*"CPU time = $runtimes"*"\n"*"Modularity = $Q"*"\n"*"GT_Mod = $Q_true"*"\n"*"Relative Mod. error = $relative_mod_error"*"\n"*"K_hat = $K_hat"*"\n"*"K_true = $K_true"*"\n"*"Relative k error = $relative_K_error"*"\n"*"Conductance_hat = $conductance_hat"*"\n"*"Instances = $(instances)")
            # write(f, "Instances = $(instances)"*"\n"*"ARI = $(string(Ari))"*"\n"*"CPU time = $runtimes"*"\n"*"Modularity = $Q"*"\n"*"GT_Mod = $Q_true"*"\n"*"REL_Q_ERR = $relative_mod_error"*"K_hat = $K_hat"*"\n"*"K_true = $K_true\n"*"REL_K_ERR = $relative_K_error"*"\n"*"Conductance_hat = $conductance_hat")
        end
    end
    # save final results
    filename= string(model,scenario,"$(version).results")
    open(filename, "a") do f
        write(f, "CPU time = $runtimes"*"\n"*"Modularity = $Q"*"\n"*"GT_Modularity = $Q_true"*"\n"*"Relative Modularity error = $relative_mod_error"*"\n"*"K = $K_hat"*"\n"*"GT_K = $K_true"*"\n"*"Relative k error = $relative_K_error"*"\n"*"Instances = $(instances)"*"\n")
        # write(f, "CPU time = $runtimes"*"\n"*"Modularity = $Q"*"\n"*"GT_Mod = $Q_true"*"\n"*"Relative Mod. error = $relative_mod_error"*"\n"*"K_hat = $K_hat"*"\n"*"K_true = $K_true"*"\n"*"Relative k error = $relative_K_error"*"\n"*"Conductance_hat = $conductance_hat"*"\n"*"Instances = $(instances)")
        # write(f, "ARI = $Ari"*"\n"*"CPU time = $runtimes"*"\n"*"Modularity = $Q"*"\n"*"GT_Mod = $Q_true"*"\n"*"Relative Mod. error = $relative_mod_error"*"\n"*"K_hat = $K_hat"*"\n"*"K_true = $K_true"*"\n"*"Relative k error = $relative_K_error"*"\n"*"Conductance_hat = $conductance_hat"*"\n"*"Instances = $(instances)")
        # write(f, "Instances = $(instances)"*"\n"*"ARI = $(string(Ari))"*"\n"*"CPU time = $runtimes"*"\n"*"Modularity = $Q"*"\n"*"GT_Mod = $Q_true"*"\n"*"REL_Q_ERR = $relative_mod_error"*"K_hat = $K_hat"*"\n"*"K_true = $K_true\n"*"Conductance_hat = $conductance_hat")
    end
end


##################
##################
main()